def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams; sort each group, then sort the groups."""
    # Find all anagrams of each word
    anagrams = {}
    for word in words:
        # Sort the word and add to the anagram dictionary
        sorted_word = ''.join(sorted(word))
        if sorted_word not in anagrams:
            anagrams[sorted_word] = [word]
        else:
            anagrams[sorted_word].append(word)

    # Sort the anagrams by their first word
    sorted_anagrams = sorted(anagrams.items(), key=lambda x: x[0])

    # Convert sorted anagrams to a list of lists
    return [list(group) for group in sorted_anagrams]

