    """Return all integers in nested (a list of ints and lists, at any depth) in one list."""

    def flatten_items(nested: list) -> list:
        """Recursively flatten a list of integers and lists."""
        flat_items = []
        for item in nested:
            if isinstance(item, list):
                flat_items.extend(flatten_items(item))
            elif isinstance(item, int):
                flat_items.append(item)
        return flat_items

    return flatten_items(nested)

