def valid_parentheses(s: str) -> bool:
    """Return True if the brackets ()[]{} in s are properly matched and nested."""
    # Initialize two empty stacks to keep track of opening and closing brackets
    stack_open = []
    stack_close = []

    # Iterate through each character in the string
    for char in s:
        if char == '(':
            stack_open.append(char)
        elif char == ')':
            if not stack_open:
                return False
            stack_close.append(char)

        # If there's no corresponding opening bracket to match, return False
        if len(stack_open) == 0 and len(stack_close) != 0:
            return False

    # If the stack of opening brackets is empty, all brackets were matched
    return len(stack_open) == 0
